tool_input.command:
$p="$env:USERPROFILE\.dsh\profiles\web\cordis.patch.yml";
Write-Output "=== config mtime ==="; (Get-Item $p).LastWriteTime;
Write-Output "=== git log (last 6) ==="; git -C "D:\repository\skills" log --oneline -6 -- dsh/profiles/web/cordis.patch.yml 2>$null;
Write-Output "=== tool-workflow / full-tools / session-query occurrences ===";
Select-String -Path $p -Pattern "tool-workflow|preset-full-tools|optional-tool-session-query|tool-schedule|tool-goal" | Select-Object LineNumber,Line | Format-Table -AutoSize;
Write-Output "=== dsh web process ==="; Get-Process node -ErrorAction SilentlyContinue | Sort-Object StartTime -Descending | Select-Object -First 5 Id,StartTime,@{n='RAM_MB';e={[int]($_.WorkingSet64/1MB)}} | Format-Table -AutoSize
